/**
Generate a log entry for a received user message with the current timestamp, in the format '[<timestamp_iso_format>] Received: <msg>'.

@param msg The user message received.

@return The log entry for the received message.
*/
char* generate_receive_log(const char *msg) {
    // Calculate the maximum possible length of the log entry:
    // Timestamp (e.g., "YYYY-MM-DDTHH:MM:SSZ") + "[] Received: " + MAX_MSG_LEN + null terminator
    // The timestamp format "%Y-%m-%dT%H:%M:%SZ" is 19 characters.
    // "[] Received: " is 13 characters.
    // MAX_MSG_LEN is 256.
    // Null terminator is 1 character.
    size_t max_log_len = 19 + strlen("[] Received: ") + MAX_MSG_LEN + 1;
    char *log_entry = (char *)malloc(max_log_len);

    if (log_entry == NULL) {
        // Allocation failed, return NULL. The caller is responsible for handling this.
        return NULL;
    }

    // Get current time
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now); // Use gmtime for UTC

    // Format timestamp in ISO 8601 format (YYYY-MM-DDTHH:MM:SSZ)
    char timestamp_buffer[30]; // Sufficient for ISO 8601 format like "YYYY-MM-DDTHH:MM:SSZ"
    strftime(timestamp_buffer, sizeof(timestamp_buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Construct the log entry using snprintf for safety.
    // We ensure that the message part does not exceed MAX_MSG_LEN.
    // The total buffer size is max_log_len, which is calculated to be sufficient.
    // We also truncate the input message if it exceeds MAX_MSG_LEN - 1 to prevent overflow.
    size_t msg_len = strlen(msg);
    size_t effective_msg_len = (msg_len < MAX_MSG_LEN) ? msg_len : (MAX_MSG_LEN - 1);

    snprintf(log_entry, max_log_len, "[%s] Received: %.*s", timestamp_buffer, (int)effective_msg_len, msg);

    // The caller is responsible for freeing the memory allocated by malloc.
    return log_entry;
}
